  margin: 0;
  flex-wrap: nowrap;
}
.empty-state-card--compact .guide-step {
  padding: 5px 12px;
  font-size: 12.5px;
}
.empty-state-card--compact .es-side .btn {
  margin: 0;
}

@media (max-width: 760px) {
  .empty-state-card--compact {
    flex-direction: column;
    align-items: flex-start;
    text-align: left;
  }
  .empty-state-card--compact .es-side {
    flex-wrap: wrap;
  }
}

/* Skeleton */
.skeleton {
  background: linear-gradient(100deg, #1a1a1a 30%, #2c2c2c 50%, #1a1a1a 70%);
  background-size: 200% 100%;
  animation: shimmer 1.4s infinite linear;
}
@keyframes shimmer {
  to {
    background-position: -200% 0;
  }
}

/* --------------------------------------------------------------------------
   Title card (16:9 landscape)
   -------------------------------------------------------------------------- */
.title-card {
  position: relative;
  width: var(--card-w);
  aspect-ratio: 16 / 9;
  border-radius: var(--radius-card);
  overflow: hidden;
  background: var(--bg-2);
  border: 1px solid transparent;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-radius 0.18s ease;
}
.title-card:hover,
.title-card:focus-within {
  transform: scale(1.05);
  z-index: 5;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.55);
}
/* While the expanded hover card (D20) is open, the base card settles back to
   its grid slot (no ring, no scale) so the portal measures the real cell. */
.title-card.tc-pop-open {
  transform: none;
  box-shadow: none;
  transition: none;
}

.title-card-fallback {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 34px;
  font-weight: 800;
  color: var(--text-3);
  background: linear-gradient(135deg, var(--bg-2), var(--bg-3));
}

/* Netflix-style wide tile (D21): portrait poster from the art volume as both
   the blurred full-bleed ground and the crisp centered figure. */
.title-card-poster .title-card-bg,
.title-card-poster .title-card-bg-empty {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.title-card-poster .title-card-bg {
  object-fit: cover;
  filter: blur(18px) brightness(0.55);
