    torrentName: 'Inception.2010.1080p',
    indexer: '1337x',
    sizeBytes: 1000,
    state: 'downloading',
    progress: 0.5,
    downloadSpeed: 100,
    uploadSpeed: 10,
    etaSeconds: 60,
    ratio: 0.1,
    contentPath: '/downloads/inception',
    streamFilePath: 'inception/Inception.mkv',
    streamable: true,
    createdAt: '2026-09-01T00:00:00.000Z',
    completedAt: null,
    resolution: null,
    source: null,
    codec: null,
    hdr: false,
    isDolbyVision: false,
    ...overrides,
  };
}

export function makeTestDeps(overrides: Partial<AppDeps> = {}): AppDeps {
  const config: AppConfig = loadConfig();
  const base: Partial<AppDeps> = {
    config,
    pool: undefined as unknown as pg.Pool,
    tmdb: {
      searchMulti: async () => [],
      details: async () => {
        throw new Error('not stubbed');
      },
      browse: async () => [],
      seasonEpisodes: async () => [],
      imdbId: async () => null,
      videos: async () => [],
      certification: async () => null,
    },
    prowlarr: {
      search: async () => [],
    },
    qbittorrent: {
      addTorrent: async () => {},
      listTorrents: async () => [],
      deleteTorrent: async () => {},
      pauseTorrent: async () => {},
      resumeTorrent: async () => {},
    },
    downloads: {
      insert: async (input: CreateDownloadInput) => makeDownloadRecord({ infoHash: input.infoHash }),
      findByInfoHash: async () => null,
      findByTorrentName: async () => null,
      list: async () => [],
      update: async () => {},
      adoptInfoHash: async () => {},
      remove: async () => {},
    },
    settings: {
      get: async () => null,
      set: async () => {},
    },
  };
  const deps = { ...base, ...overrides } as Partial<AppDeps>;
  return deps as AppDeps;
}

export function asAny(value: unknown) {
  return value as never;
}

export type { TorrentState };

